subsection.content:
Syntaxe algorithmique :

VAR

  Nom_tableau : TABLEAU [indice_minimum .. indice_maximum] DE type_des_éléments ;

Exemple :

Tab : TABLEAU [1 .. 100] D'Entier ;

Note : TABLEAU [1 .. 10] DE Réel ;

Algorithme :

ALGORITHME Lecture_Affichage ;

CONST N = 10 ;

VAR

  Tab : TABLEAU [1..N] d'Entier ;

  i : Entier ;

DÉBUT

  POUR i ALLANT DE 1 A N FAIRE

    LIRE(Tab[i]) ;

  FIN POUR ;

  POUR i ALLANT DE 1 A N FAIRE

    ÉCRIRE(Tab[i]) ;

  FIN POUR ;

FIN.

Algorithme :

ALGORITHME Add_Tab ;

CONST M = 100 ;

VAR

  T1, T2, T3 : TABLEAU [1..M] d'Entier ;

  i, N : Entier ;

DÉBUT

  RÉPÉTER

    ÉCRIRE("Donnez la taille des vecteurs");

    LIRE(N);

  JUSQU'À (N <= M) ET (N>0);

  POUR i ALLANT DE 1 À N FAIRE

    LIRE(T1[i]);

  FIN POUR;

  POUR i ALLANT DE 1 À N FAIRE

    LIRE(T2[i]);

  FIN POUR;

  POUR i ALLANT DE 1 À N FAIRE

    T3[i] <- T1[i] + T2[i];

  FIN POUR;

  POUR i ALLANT DE 1 À N FAIRE

    ÉCRIRE(T3[i]);

  FIN POUR;

FIN.

Algorithme :

ALGORITHME Recherche;

CONST M = 20;

VAR

  V : TABLEAU[1..M] D'Entier;

  D, i: Entier;

  Trouve : Booléen;

DÉBUT

  (* remplir le vecteur V *)

  POUR i ALLANT DE 1 à M FAIRE

    LIRE(V[i]);

  FIN POUR;

  (* lire la valeur recherchée *)

  ÉCRIRE("Veuillez saisir la valeur recherchée");

  LIRE(D);

  (* vérifier si la valeur recherchée existe dans le vecteur *)

  i <- 1;

  Trouve <- Faux;

  TANT QUE (i <= M) ET (NON Trouve) FAIRE

    SI (V[i] = D) ALORS

      Trouve <- Vrai;

    SINON

      i <- i + 1;

    FIN SI;

  FIN TANT QUE;

  (* afficher la position de la valeur recherchée si elle existe *)

  SI (Trouve = Vrai) ALORS

    ÉCRIRE("La position de la valeur recherchée est : ", i);

  SINON

    ÉCRIRE("La valeur recherchée n'existe pas dans le tableau");

  FIN SI;

FIN.

Syntaxe algorithmique :

VAR

  Nom_matrice : TABLEAU [inf_ligne .. max_ligne, inf_colonne .. max_colonne] DE type_des_éléments ;

Exemple :

Achat : TABLEAU [1 .. 100, 1 .. 100] d'Entier ;

Vente : TABLEAU [1 .. 10, 1 .. 47] de Réel ;

Algorithme de lecture :

ALGORITHME Lectur_Mat ;

CONST N = 3 ; M = 4 ;

VAR

  Mate : TABLEAU [1 .. N, 1 .. M] d'Entier ;

  i, j : Entier ;

DÉBUT

  POUR i ALLANT DE 1 A N FAIRE

    POUR j ALLANT DE 1 A M FAIRE

      LIRE(Mate[i, j]);

    FIN POUR ;

  FIN POUR ;

FIN.

Algorithme d'écriture :

ALGORITHME Ecriture_Mat ;

VAR

  Mate : TABLEAU [1 .. 3, 1 .. 4] d'Entier ;

  i, j : Entier ;

DÉBUT

  POUR i ALLANT DE 1 A N FAIRE

    POUR j ALLANT DE 1 A M FAIRE

      ÉCRIRE(Mate[i, j]);

    FIN POUR ;

  FIN POUR ;

FIN.

Algorithme :

ALGORITHME ADD_Mat ;

CONST NL = 10 ; NC = 20 ;

VAR

  Mat1, Mat2 : TABLEAU [1..NL,1..NC] d'Entier ;

  i, j : Entier ;

DÉBUT

  (* remplir la matrice Mat1 *)

  POUR i ALLANT DE 1 à NL FAIRE

    POUR j ALLANT DE 1 à NC FAIRE

      LIRE(Mat1[i, j]);

    FIN POUR ;

  FIN POUR ;

  (* remplir la matrice Mat2 *)

  POUR i ALLANT DE 1 à NL FAIRE

    POUR j ALLANT DE 1 à NC FAIRE

      LIRE(Mat2[i, j]);

    FIN POUR ;

  FIN POUR ;

  (* additionner les deux matrices *)

  POUR i ALLANT DE 1 à NL FAIRE

    POUR j ALLANT DE 1 à NC FAIRE

      Mat3[i, j] <- Mat1[i,j] + Mat2[i,j];

    FIN POUR ;

  FIN POUR ;

  (* afficher la matrice résultante Mat3 *)

  POUR i ALLANT DE 1 à NL FAIRE

    POUR j ALLANT DE 1 à NC FAIRE

      ÉCRIRE(Mat3[i, j]);

    FIN POUR ;

  FIN POUR ;

FIN.
